const empty=(title,text,link='',label='')=>`<div class="empty"><span class="empty-symbol" aria-hidden="true">✧</span><h3>${esc(title)}</h3><p>${esc(text)}</p>${link?`<a class="button secondary" href="${esc(link)}">${esc(label)}</a>`:''}</div>`;
function notice(text,error=false){const n=$('#notice');n.textContent=text;n.className=error?'error':'';n.hidden=false;}
async function api(path,method='GET',data){const options={method};if(data instanceof FormData)options.body=data;else if(data!==undefined){options.headers={'Content-Type':'application/json'};options.body=JSON.stringify(data);}const response=await fetch(path,options);if(response.status===401&&!path.startsWith('/api/auth/')){showAuth('login');throw Error('Tu sesión terminó. Vuelve a iniciar sesión.');}let value;try{value=await response.json();}catch{throw Error('El servidor no devolvió una respuesta válida. Revisa la conexión.');}if(!response.ok){let detail=value.detail;throw Error(typeof detail==='string'?detail:Array.isArray(detail)?detail.map(d=>d.msg).join(' · '):detail?.message||'No se pudo completar la operación.');}return value;}
function busy(button,fn){return async event=>{event?.preventDefault();if(button?.disabled)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Un momento…';}try{await fn(event);}catch(e){notice(e.message,true);}finally{if(button){button.disabled=false;if(button.textContent==='Un momento…')button.textContent=original;}}};}
