const portalOf=url=>{try{const h=new URL(url).hostname;return Object.keys(autoPortals).find(k=>h.includes(k))||'';}catch{return '';}};
const runLabels={en_cola:'En cola',ejecutando:'Postulando ahora…',postulada:'Postulación confirmada',bloqueada:'Necesita tu intervención',intento_no_confirmado:'Sin confirmación del portal',error:'No se completó (no se envió)'};
const actionLabels={registrada:'Oportunidad guardada',auto_postulacion_autorizada:'Postulación automática autorizada',auto_postulacion_iniciada:'JobFlow abrió el portal',postulada:'Postulación confirmada',bloqueada:'Detenida: necesita tu intervención',intento_no_confirmado:'Intento sin confirmación',auto_postulacion_error:'Error técnico antes de enviar',cv_adaptado:'CV adaptado',cv_aprobado:'CV aprobado',preparada:'Respuestas preparadas',respuestas_aprobadas:'Respuestas aprobadas',preguntas_pendientes:'Postulada: quedan preguntas por responder',preguntas_respondidas:'Respuestas enviadas al portal'};
function confirmDialog(title,html,ok='Autorizar',destructive=false){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-body').innerHTML=html;$('#confirm-ok').textContent=ok;$('#confirm-ok').classList.toggle('destructive',destructive);d.returnValue='';d.onclose=()=>resolve(d.returnValue==='ok');d.showModal();});}
function sentData(){const p=state.profile||{};return `<p>JobFlow solo usará tu perfil confirmado y las respuestas que aprobaste:</p><ul>${[['Pretensión salarial',p.rango_salarial],['Disponibilidad',p.disponibilidad],['Movilidad',p.movilidad],['Correo',p.email],['Teléfono',p.telefono]].filter(([,v])=>v).map(([k,v])=>`<li>${k}: ${esc(v)}</li>`).join('')}</ul><p class="muted-note">Si aparece una pregunta sin dato confirmado, un CAPTCHA, una prueba o una casilla de términos, se detiene y te avisa. Solo marca “postulada” cuando el portal lo confirma.</p>`;}
function href(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?esc(u.href):'';}catch{return '';}}
function dateLabel(value){if(!value)return '';const raw=/Z$|[+-]\d\d:\d\d$/.test(value)?value:value+'Z';return new Date(raw).toLocaleString('es-PE',{timeZone:state.setup?.settings.timezone||'America/Lima',dateStyle:'medium',timeStyle:'short'});}
function input(label,name,value='',type='text',full=false){return `<label class="${full?'full':''}">${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}"></label>`;}
const salaryRanges=['Hasta S/1,500','S/1,500 – S/2,000','S/2,000 – S/2,500','S/2,500 – S/3,000','S/3,000 – S/3,500','S/3,500 – S/4,000','S/4,000 – S/5,000','S/5,000 – S/6,000','S/6,000 – S/8,000','Más de S/8,000'];
const restrictionOptions=['Sin turnos nocturnos','Sin horarios rotativos','Sin trabajo los fines de semana','Solo en planilla (con beneficios de ley)','Sueldo fijo (no solo comisiones)','Sin ventas de campo','Sin viajes frecuentes','Solo medio tiempo'];
